-- Base ISA padronizada: 98 bacias, 255 sub-bacias
CREATE DATABASE IF NOT EXISTS isa_bh DEFAULT CHARACTER SET utf8mb4;
USE isa_bh;
SET NAMES utf8mb4;
DROP TABLE IF EXISTS sub_bacia;
DROP TABLE IF EXISTS bacia;
CREATE TABLE bacia (
  id_bacia INT NOT NULL,
  nome_bacia VARCHAR(120) NOT NULL,
  PRIMARY KEY (id_bacia)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sub_bacia (
  id_sub_bacia INT NOT NULL,
  cod_sub_bacia INT NOT NULL,
  id_bacia INT NOT NULL,
  area_ha DECIMAL(10,2),
  area_km2 DECIMAL(10,4),
  populacao INT,
  densidade_hab_ha DECIMAL(8,2),
  pop_sem_rede_coletora INT,
  pop_com_rede_coletora INT,
  pop_sem_interceptacao INT,
  pop_com_interceptacao INT,
  pop_cf INT,
  pop_sem_coleta_lixo_cf INT,
  pop_com_coleta_lixo_cf INT,
  pop_sem_coleta_lixo_vf INT,
  pop_com_coleta_lixo_vf INT,
  pop_sem_coleta_lixo_cfvf INT,
  pop_com_coleta_lixo_cfvf INT,
  pop_mancha_inundacao INT,
  iab DECIMAL(4,3),
  ice DECIMAL(4,3),
  iie DECIMAL(4,3),
  ies DECIMAL(4,3),
  icl_cf DECIMAL(4,3),
  icl_vf DECIMAL(4,3),
  icl DECIMAL(4,3),
  idr DECIMAL(4,3),
  isa DECIMAL(4,3),
  sem_populacao TINYINT(1) NOT NULL,
  faixa_isa VARCHAR(10),
  outlier_isa TINYINT(1) NOT NULL,
  PRIMARY KEY (id_sub_bacia),
  UNIQUE (cod_sub_bacia),
  CONSTRAINT fk_sub_bacia_bacia FOREIGN KEY (id_bacia) REFERENCES bacia (id_bacia)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX idx_sub_bacia_isa ON sub_bacia (isa);
